<script setup lang="ts">
import Stage1Field from './Stage1Field.vue';import Stage1Files from './Stage1Files.vue'
const props=defineProps<{modelValue:Record<string,any>;types:Record<string,any>[];categories:Record<string,any>[];disabled?:boolean;receiptKey?:string}>(),emit=defineEmits<{(e:'update:modelValue',value:Record<string,any>):void}>()
const set=(key:string,value:unknown)=>emit('update:modelValue',{...props.modelValue,[key]:value,...(key==='type'?{categoryIds:[]}:{} )})
</script>
<template><view class="s1-qualification-form"><Stage1Field label="资质类型" type="select" :model-value="modelValue.type" :options="types.map(t=>({value:t.code,label:t.code==='BUSINESS_LICENSE'?'营业执照':t.code==='FOOD_LICENSE'?'食品经营许可证':t.code}))" :disabled="disabled" required @update:model-value="set('type',$event)"/><Stage1Field label="证照主体名称" :model-value="modelValue.holder" :disabled="disabled" required :maximum="100" @update:model-value="set('holder',$event)"/><Stage1Field label="证照编号" :model-value="modelValue.number" :disabled="disabled" required :maximum="100" @update:model-value="set('number',$event)"/><Stage1Field label="发证机关" :model-value="modelValue.issuer" :disabled="disabled" :maximum="100" @update:model-value="set('issuer',$event)"/><Stage1Field label="有效期开始" type="date" :model-value="modelValue.validFrom" :disabled="disabled" required @update:model-value="set('validFrom',$event)"/><Stage1Field label="长期有效" type="boolean" :model-value="modelValue.longTerm" :disabled="disabled" @update:model-value="emit('update:modelValue',{...modelValue,longTerm:$event,validThrough:$event?null:modelValue.validThrough})"/><Stage1Field v-if="!modelValue.longTerm" label="有效期截止" type="date" :model-value="modelValue.validThrough" :disabled="disabled" required @update:model-value="set('validThrough',$event)"/><Stage1Field v-if="types.find(t=>t.code===modelValue.type)?.scope==='CATEGORY'" label="专项资质适用类目" type="multi" :options="categories.map(c=>({value:c.id,label:c.name}))" :model-value="modelValue.categoryIds||[]" :disabled="disabled" required @update:model-value="set('categoryIds',$event)"/><Stage1Files label="证照附件" :receipt-key="receiptKey" purpose="QUALIFICATION" :model-value="modelValue.fileIds||[]" :disabled="disabled" @update:model-value="set('fileIds',$event)"/></view></template>
<style scoped lang="scss">.s1-qualification-form{display:flex;flex-direction:column;gap:$space-4}</style>
